from AlgorithmImports import *

class QuantConnectAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        for ticker in self.tickers:
            self.AddEquity(ticker, Resolution.Daily)

        self.spy_sma_period = 20
        self.spy_prices = []

        self.aapl_prices = []
        self.aapl_red_streak = 0
        self.aapl_rsi_period = 14

    def OnData(self, data):
        for ticker in self.tickers:
            if ticker not in data or data[ticker] is None:
                return

        spy_close = data["SPY"].Close
        aapl_close = data["AAPL"].Close

        self.spy_prices.append(spy_close)
        self.aapl_prices.append(aapl_close)

        if len(self.spy_prices) < self.spy_sma_period + 1:
            return
        if len(self.aapl_prices) < self.aapl_rsi_period + 1:
            return

        spy_holdings = self.Portfolio["SPY"].Quantity
        aapl_holdings = self.Portfolio["AAPL"].Quantity

        spy_sma_yesterday = sum(self.spy_prices[-self.spy_sma_period-1:-1]) / self.spy_sma_period
        spy_sma_today = sum(self.spy_prices[-self.spy_sma_period:]) / self.spy_sma_period
        spy_close_yesterday = self.spy_prices[-2]

        aapl_rsi = self.CalculateRSI(self.aapl_prices, self.aapl_rsi_period)

        if len(self.aapl_prices) > 1:
            if self.aapl_prices[-1] < self.aapl_prices[-2]:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        if spy_holdings > 0:
            spy_close_yesterday_at_or_above_sma = spy_close_yesterday >= spy_sma_yesterday
            spy_close_today_below_sma = spy_close < spy_sma_today
            if spy_close_yesterday_at_or_above_sma and spy_close_today_below_sma:
                self.Sell("SPY", spy_holdings)

        if aapl_holdings > 0:
            if aapl_rsi > 60:
                self.Sell("AAPL", aapl_holdings)

        if spy_holdings == 0:
            spy_close_yesterday_at_or_below_sma = spy_close_yesterday <= spy_sma_yesterday
            spy_close_today_above_sma = spy_close > spy_sma_today
            if spy_close_yesterday_at_or_below_sma and spy_close_today_above_sma:
                target_value = self.Portfolio.TotalPortfolioValue * 0.4
                shares = int(target_value / spy_close)
                if shares > 0:
                    self.Buy("SPY", shares)

        if aapl_holdings == 0:
            if self.aapl_red_streak >= 3:
                cash = self.Portfolio.Cash
                if cash >= 20000:
                    shares = int(20000 / aapl_close)
                    if shares > 0:
                        self.Buy("AAPL", shares)

    def CalculateRSI(self, closes, period):
        if len(closes) < period + 1:
            return None

        gains = 0
        losses = 0

        for i in range(-period, 0):
            change = closes[i] - closes[i - 1]
            if change > 0:
                gains += change
            else:
                losses -= change

        avg_gain = gains / period
        avg_loss = losses / period

        if avg_loss == 0:
            return 100

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        return rsi

