class TradeAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.sma_spy = self.SMA("SPY", 50, Resolution.Daily)
        self.rsi_aapl = self.RSI("AAPL", 14, Resolution.Daily)

        self.prev_spy_close = None
        self.prev_sma_value = None
        self.prev_aapl_close = None
        self.consecutive_red_days = 0

    def OnData(self, data):
        if not all(sym in data for sym in [self.spy, self.aapl, self.ibm, self.bac, self.aig]):
            return

        if not self.sma_spy.IsReady or not self.rsi_aapl.IsReady:
            return

        spy_close = data[self.spy].Close
        aapl_close = data[self.aapl].Close
        sma_value = self.sma_spy.Current.Value
        rsi_value = self.rsi_aapl.Current.Value

        if self.prev_aapl_close is not None:
            if aapl_close < self.prev_aapl_close:
                self.consecutive_red_days += 1
            else:
                self.consecutive_red_days = 0

        self._process_sells(spy_close, sma_value, rsi_value)
        self._process_buys(spy_close, sma_value, aapl_close)

        self.prev_spy_close = spy_close
        self.prev_sma_value = sma_value
        self.prev_aapl_close = aapl_close

    def _process_sells(self, spy_close, sma_value, rsi_value):
        if self.Portfolio[self.spy].Quantity > 0:
            if self.prev_spy_close is not None and self.prev_sma_value is not None:
                if self.prev_spy_close >= self.prev_sma_value and spy_close < sma_value:
                    self.Liquidate(self.spy)

        if self.Portfolio[self.aapl].Quantity > 0:
            if rsi_value > 60:
                self.Liquidate(self.aapl)

    def _process_buys(self, spy_close, sma_value, aapl_close):
        if self.Portfolio[self.spy].Quantity == 0:
            if self.prev_spy_close is not None and self.prev_sma_value is not None:
                if self.prev_spy_close <= self.prev_sma_value and spy_close > sma_value:
                    invest_amount = self.Portfolio.TotalPortfolioValue * 0.4
                    shares = int(invest_amount / spy_close)
                    if shares > 0:
                        self.Buy(self.spy, shares)

        if self.Portfolio[self.aapl].Quantity == 0:
            if self.consecutive_red_days >= 3:
                if self.Portfolio.Cash >= 20000:
                    shares = int(20000 / aapl_close)
                    if shares > 0:
                        self.Buy(self.aapl, shares)

