from AlgorithmImport import *

class LeanAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma_period = 20
        self.spy_closes = []

        self.aapl_rsi_period = 14
        self.aapl_closes = []
        self.aapl_red_days = 0

    def OnData(self, data):
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            if self.symbols[ticker] not in data:
                return

        spy_close = data[self.symbols["SPY"]].Close
        aapl_close = data[self.symbols["AAPL"]].Close

        self.spy_closes.append(spy_close)
        self.aapl_closes.append(aapl_close)

        spy_sma = self._calculate_sma(self.spy_closes, self.spy_sma_period)
        spy_sma_prev = self._calculate_sma_prev(self.spy_closes, self.spy_sma_period)

        aapl_rsi = self._calculate_rsi(self.aapl_closes, self.aapl_rsi_period)

        if len(self.aapl_closes) >= 2:
            if self.aapl_closes[-1] < self.aapl_closes[-2]:
                self.aapl_red_days += 1
            else:
                self.aapl_red_days = 0

        spy_sma_ready = spy_sma is not None and spy_sma_prev is not None

        if spy_sma_ready and self.Portfolio[self.symbols["SPY"]].Quantity > 0:
            if self.spy_closes[-2] >= spy_sma_prev and self.spy_closes[-1] < spy_sma:
                self.Liquidate(self.symbols["SPY"])

        if aapl_rsi is not None and self.Portfolio[self.symbols["AAPL"]].Quantity > 0:
            if aapl_rsi > 60:
                self.Liquidate(self.symbols["AAPL"])

        if spy_sma_ready and self.Portfolio[self.symbols["SPY"]].Quantity == 0:
            if self.spy_closes[-2] <= spy_sma_prev and self.spy_closes[-1] > spy_sma:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                shares_to_buy = int(portfolio_value * 0.4 / spy_close)
                if shares_to_buy > 0:
                    self.Buy(self.symbols["SPY"], shares_to_buy)

        if self.Portfolio[self.symbols["AAPL"]].Quantity == 0:
            if self.aapl_red_days >= 3:
                if self.Portfolio.Cash >= 20000:
                    shares_to_buy = int(20000 / aapl_close)
                    if shares_to_buy > 0:
                        self.Buy(self.symbols["AAPL"], shares_to_buy)

    def _calculate_sma(self, prices, period):
        if len(prices) < period:
            return None
        return sum(prices[-period:]) / period

    def _calculate_sma_prev(self, prices, period):
        if len(prices) < period + 1:
            return None
        return sum(prices[-(period+1):-1]) / period

    def _calculate_rsi(self, prices, period):
        if len(prices) < period + 1:
            return None

        closes = prices[-(period+1):]
        gains = 0
        losses = 0

        for i in range(1, len(closes)):
            change = closes[i] - closes[i-1]
            if change > 0:
                gains += change
            else:
                losses -= change

        avg_gain = gains / period
        avg_loss = losses / period

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 50

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        return rsi

