class QuantConnectLeanAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        # Strategy A: SPY with 20-day SMA
        self.a_lot = 0
        self.a_closes = []
        self.a_sma_period = 20
        self.a_prev_above = None

        # Strategy B: AAPL with RSI(14) and red day tracking
        self.b_lot = 0
        self.b_closes = []
        self.b_rsi = RelativeStrengthIndex(14)
        self.b_red_consecutive = 0

    def OnData(self, data):
        # Check all required tickers have data
        for ticker in self.symbols:
            if not data.ContainsKey(self.symbols[ticker]):
                return

        spy_close = data[self.symbols["SPY"]].Close
        aapl_close = data[self.symbols["AAPL"]].Close

        # === Strategy A: SPY with SMA ===
        self.a_closes.append(spy_close)

        if len(self.a_closes) >= self.a_sma_period:
            sma = sum(self.a_closes[-self.a_sma_period:]) / self.a_sma_period
            is_above = spy_close > sma

            if self.a_prev_above is not None:
                # Sell first (if lot non-empty)
                if self.a_lot > 0:
                    # Cross below: was above, now not above
                    if self.a_prev_above and not is_above:
                        self.MarketOrder(self.symbols["SPY"], -self.a_lot)
                        self.a_lot = 0

                # Buy (if lot empty)
                if self.a_lot == 0:
