        ma_yesterday = sum(self.spy_prices[-(ma_period+1):-1]) / ma_period
        rsi = self.CalculateRSI(self.aapl_prices, rsi_period)

        if self.aapl_prices[-1] < self.aapl_prices[-2]:
            self.aapl_red_days += 1
        else:
            self.aapl_red_days = 0

        if self.spy_shares > 0:
            spy_prev = self.spy_prices[-2]
            if spy_prev > ma_yesterday and spy_close <= ma_today:
                self.MarketOrder("SPY", -self.spy_shares)
                self.spy_shares = 0

        if self.spy_shares == 0:
            spy_prev = self.spy_prices[-2]
            if spy_prev <= ma_yesterday and spy_close > ma_today:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                invest_amount = portfolio_value * 0.4
                shares = int(invest_amount / spy_close)
                if shares > 0:
                    self.MarketOrder("SPY", shares)
                    self.spy_shares = shares

        if self.aapl_shares > 0:
            if rsi > 60:
                self.MarketOrder("AAPL", -self.aapl_shares)
                self.aapl_shares = 0

        if self.aapl_shares == 0:
            if self.aapl_red_days >= 3:
                cash = self.Portfolio.Cash
                if cash >= 20000:
                    shares = int(20000 / aapl_close)
                    self.MarketOrder("AAPL", shares)
                    self.aapl_shares = shares

    def CalculateRSI(self, prices, period):
        if len(prices) < period + 1:
            return 50

        recent = prices[-(period+1):]
        gains = 0.0
        losses = 0.0
        for i in range(1, len(recent)):
            change = recent[i] - recent[i-1]
            if change > 0:
                gains += change
            else:
                losses -= change

        avg_gain = gains / period
        avg_loss = losses / period

        if avg_loss == 0:
            return 100.0

        rs = avg_gain / avg_loss
        return 100.0 - (100.0 / (1.0 + rs))

