                self.price_windows[symbol].Add(float(data[symbol].Close))

        if available_symbols != set(self.symbols):
            return

        if any(window.Count < 21 for window in self.price_windows.values()):
            return

        self.execute_strategies(data)

    def execute_strategies(self, data):
        spy_close = float(data["SPY"].Close)
        aapl_close = float(data["AAPL"].Close)

        spy_closes = list(self.price_windows["SPY"])
        aapl_closes = list(self.price_windows["AAPL"])

        yesterday_spy = spy_closes[-2]
        today_spy = spy_closes[-1]
        yesterday_aapl = aapl_closes[-2]
        today_aapl = aapl_closes[-1]

        yesterday_ma_spy = sum(spy_closes[-21:-1]) / 20
        today_ma_spy = sum(spy_closes[-20:]) / 20

        if today_aapl < yesterday_aapl:
            red_count = 1
            for i in range(len(aapl_closes) - 2, 0, -1):
                if aapl_closes[i] < aapl_closes[i-1]:
                    red_count += 1
                else:
                    break
            self.aapl_red_days = red_count
        else:
            self.aapl_red_days = 0

        aapl_rsi = self.calculate_rsi(aapl_closes)

        if self.strategy_a_shares > 0:
            if yesterday_spy >= yesterday_ma_spy and today_spy < today_ma_spy:
                self.MarketOrder("SPY", -self.strategy_a_shares)
                self.strategy_a_shares = 0

        if self.strategy_a_shares == 0:
            if yesterday_spy <= yesterday_ma_spy and today_spy > today_ma_spy:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                invest_amount = portfolio_value * 0.40
                shares_to_buy = int(invest_amount / spy_close)
                if shares_to_buy > 0:
                    self.MarketOrder("SPY", shares_to_buy)
                    self.strategy_a_shares = shares_to_buy

        if self.strategy_b_shares > 0:
            if aapl_rsi is not None and aapl_rsi > 60:
                self.MarketOrder("AAPL", -self.strategy_b_shares)
                self.strategy_b_shares = 0

        if self.strategy_b_shares == 0:
            if self.aapl_red_days >= 3:
                cash_available = self.Portfolio.Cash
                if cash_available >= 20000:
                    shares_to_buy = int(20000 / aapl_close)
                    if shares_to_buy > 0:
                        self.MarketOrder("AAPL", shares_to_buy)
                        self.strategy_b_shares = shares_to_buy

    def calculate_rsi(self, closes):
        if len(closes) < 15:
            return None

        recent_closes = closes[-15:]

        gains = 0.0
        losses = 0.0

        for i in range(1, len(recent_closes)):
            change = recent_closes[i] - recent_closes[i-1]
            if change > 0:
                gains += change
            else:
                losses -= change

        avg_gain = gains / 14
        avg_loss = losses / 14

        if avg_loss == 0:
            return 100.0

        rs = avg_gain / avg_loss
        rsi = 100.0 - (100.0 / (1.0 + rs))

        return rsi
