        spy_close = data[self.symbols["SPY"]].Close
        aapl_close = data[self.symbols["AAPL"]].Close

        self.spy_closes.append(spy_close)
        self.aapl_closes.append(aapl_close)

        if len(self.spy_closes) < 101 or len(self.aapl_closes) < 14:
            return

        spy_sma_today = np.mean(self.spy_closes[-100:])
        spy_sma_yesterday = np.mean(self.spy_closes[-101:-1])

        aapl_rsi = self.calculate_rsi(self.aapl_closes, 14)

        aapl_prev_close = self.aapl_closes[-2]
        if aapl_close < aapl_prev_close:
            self.strategy_b_red_days += 1
        else:
            self.strategy_b_red_days = 0

        spy_close_yesterday = self.spy_closes[-2]

        # SELL
        if self.Portfolio[self.symbols["SPY"]].Quantity > 0:
            if spy_close_yesterday >= spy_sma_yesterday and spy_close < spy_sma_today:
                self.Liquidate(self.symbols["SPY"])

        if self.Portfolio[self.symbols["AAPL"]].Quantity > 0:
            if aapl_rsi > 60:
                self.Liquidate(self.symbols["AAPL"])

        # BUY
        if self.Portfolio[self.symbols["SPY"]].Quantity == 0:
            if spy_close_yesterday <= spy_sma_yesterday and spy_close > spy_sma_today:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                invest_amount = portfolio_value * 0.40
                qty = int(invest_amount / spy_close)
                if qty > 0:
                    self.Buy(self.symbols["SPY"], qty)

        if self.Portfolio[self.symbols["AAPL"]].Quantity == 0:
            if self.strategy_b_red_days >= 3:
                cash = self.Portfolio.Cash
                if cash >= 20000:
                    qty = int(20000 / aapl_close)
                    if qty > 0:
                        self.Buy(self.symbols["AAPL"], qty)

    def calculate_rsi(self, prices, period):
        if len(prices) < period:
            return 50

        recent = prices[-period:]

        up = 0
        down = 0

        for i in range(1, len(recent)):
            diff = recent[i] - recent[i-1]
            if diff > 0:
                up += diff
            else:
                down += -diff

        up_avg = up / (len(recent) - 1)
        down_avg = down / (len(recent) - 1)

        if down_avg == 0:
            return 100 if up_avg > 0 else 50

        rs = up_avg / down_avg
        rsi = 100 - (100 / (1 + rs))

        return rsi

