class DualSlotAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        # Subscribe to equities
        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in self.tickers:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        # Indicators
        self.spy_sma100 = self.SMA(self.symbols["SPY"], 100, Resolution.Daily)
        self.aapl_rsi14 = self.RSI(self.symbols["AAPL"], 14, Resolution.Daily)

        # Track previous values for crosses and red days
        self.prev_close = {}
        self.prev_spy_sma = None
        self.red_day_count = 0
        self.initialized = False

    def OnData(self, data):
        # Skip if any required symbol is missing
        if not all(self.symbols[ticker] in data for ticker in self.tickers):
            return

        # Wait until indicators are ready
        if not self.spy_sma100.IsReady or not self.aapl_rsi14.IsReady:
            return

        # Initialize on first ready bar
        if not self.initialized:
            for ticker in self.tickers:
                self.prev_close[ticker] = data[self.symbols[ticker]].Close
            self.prev_spy_sma = self.spy_sma100.Current.Value
            self.red_day_count = 0
            self.initialized = True
            return

        # Get current bar data
        current_spy_close = data[self.symbols["SPY"]].Close
        current_aapl_close = data[self.symbols["AAPL"]].Close
        prev_spy_close = self.prev_close["SPY"]
        prev_aapl_close = self.prev_close["AAPL"]

        # Get current indicator values
        current_spy_sma = self.spy_sma100.Current.Value
        current_aapl_rsi = self.aapl_rsi14.Current.Value

        # Update red day count for AAPL
        if current_aapl_close < prev_aapl_close:
            self.red_day_count += 1
        else:
            self.red_day_count = 0

        # Strategy A (SPY)
        # Sell: crosses below SMA100
        if self.Portfolio[self.symbols["SPY"]].Quantity > 0:
            if prev_spy_close >= self.prev_spy_sma and current_spy_close < current_spy_sma:
                self.Liquidate(self.symbols["SPY"])

        # Buy: crosses above SMA100
        if self.Portfolio[self.symbols["SPY"]].Quantity == 0:
            if prev_spy_close <= self.prev_spy_sma and current_spy_close > current_spy_sma:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                investment_amount = portfolio_value * 0.4
                shares_to_buy = int(investment_amount / current_spy_close)
                if shares_to_buy > 0:
                    self.Buy(self.symbols["SPY"], shares_to_buy)

        # Strategy B (AAPL)
        # Sell: RSI > 60
        if self.Portfolio[self.symbols["AAPL"]].Quantity > 0:
            if current_aapl_rsi > 60:
                self.Liquidate(self.symbols["AAPL"])

        # Buy: 3 consecutive red days
        if self.Portfolio[self.symbols["AAPL"]].Quantity == 0:
            if self.red_day_count >= 3:
                cash = self.Portfolio.Cash
                if cash >= 20000:
                    shares_to_buy = int(20000 / current_aapl_close)
                    self.Buy(self.symbols["AAPL"], shares_to_buy)

        # Update previous values
        for ticker in self.tickers:
            self.prev_close[ticker] = data[self.symbols[ticker]].Close
        self.prev_spy_sma = current_spy_sma

