    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in self.tickers:
            symbol = self.AddEquity(ticker, Resolution.Daily).Symbol
            self.symbols[ticker] = symbol

        self.strategyA_shares = 0
        self.strategyA_prices = []

        self.strategyB_shares = 0
        self.strategyB_prev_close = None
        self.strategyB_red_days = 0
        self.strategyB_prices = []

    def OnData(self, data):
        if not all(self.symbols[ticker] in data for ticker in self.tickers):
            return

        spy_close = data[self.symbols["SPY"]].Close
        aapl_close = data[self.symbols["AAPL"]].Close

        self.strategyA_prices.append(spy_close)
        if len(self.strategyA_prices) > 100:
            self.strategyA_prices.pop(0)

        if self.strategyB_prev_close is not None:
            if aapl_close < self.strategyB_prev_close:
                self.strategyB_red_days += 1
            else:
                self.strategyB_red_days = 0
        self.strategyB_prev_close = aapl_close

        self.strategyB_prices.append(aapl_close)
        if len(self.strategyB_prices) > 14:
            self.strategyB_prices.pop(0)

        if len(self.strategyA_prices) < 101:
            return

        self._execute_strategy_a(spy_close)
        self._execute_strategy_b(aapl_close)

    def _execute_strategy_a(self, spy_close):
        sma_today = np.mean(self.strategyA_prices[-100:])
        sma_yesterday = np.mean(self.strategyA_prices[-101:-1])
        spy_yesterday = self.strategyA_prices[-2]

        if self.strategyA_shares > 0:
            if spy_yesterday > sma_yesterday and spy_close <= sma_today:
                self.Sell(self.symbols["SPY"], self.strategyA_shares)
                self.strategyA_shares = 0

        if self.strategyA_shares == 0:
            if spy_yesterday <= sma_yesterday and spy_close > sma_today:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                target_value = portfolio_value * 0.4
                shares_to_buy = int(target_value / spy_close)
                if shares_to_buy > 0:
                    self.Buy(self.symbols["SPY"], shares_to_buy)
                    self.strategyA_shares = shares_to_buy

    def _execute_strategy_b(self, aapl_close):
        rsi = self._calculate_rsi(self.strategyB_prices)

        if self.strategyB_shares > 0:
            if rsi is not None and rsi > 60:
                self.Sell(self.symbols["AAPL"], self.strategyB_shares)
                self.strategyB_shares = 0

        if self.strategyB_shares == 0:
            if self.strategyB_red_days >= 3:
                cash = self.Portfolio.Cash
                if cash >= 20000:
                    shares_to_buy = int(20000 / aapl_close)
                    if shares_to_buy > 0:
                        self.Buy(self.symbols["AAPL"], shares_to_buy)
                        self.strategyB_shares = shares_to_buy

    def _calculate_rsi(self, prices):
        if len(prices) < 14:
            return None

        recent_prices = prices[-14:]
        gains = 0.0
        losses = 0.0

        for i in range(1, len(recent_prices)):
            change = recent_prices[i] - recent_prices[i - 1]
            if change > 0:
                gains += change
            else:
                losses -= change

        avg_gain = gains / 14.0
        avg_loss = losses / 14.0

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 50

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        return rsi

