            "SPY": self.AddEquity("SPY", Resolution.Daily).Symbol,
            "AAPL": self.AddEquity("AAPL", Resolution.Daily).Symbol,
            "IBM": self.AddEquity("IBM", Resolution.Daily).Symbol,
            "BAC": self.AddEquity("BAC", Resolution.Daily).Symbol,
            "AIG": self.AddEquity("AIG", Resolution.Daily).Symbol,
        }

        self.price_history = {
            "SPY": [],
            "AAPL": [],
            "IBM": [],
            "BAC": [],
            "AIG": []
        }

    def OnData(self, data):
        for symbol_name in self.symbols:
            symbol = self.symbols[symbol_name]
            if not data.ContainsKey(symbol):
                return

        for symbol_name in self.symbols:
            symbol = self.symbols[symbol_name]
            self.price_history[symbol_name].append(data[symbol].Close)

        if len(self.price_history["SPY"]) < 101 or len(self.price_history["AAPL"]) < 15:
            return

        spy_close = data[self.symbols["SPY"]].Close
        aapl_close = data[self.symbols["AAPL"]].Close

        spy_prices = self.price_history["SPY"]
        aapl_prices = self.price_history["AAPL"]

        sma_today = sum(spy_prices[-100:]) / 100
        sma_yesterday = sum(spy_prices[-101:-1]) / 100

        rsi_14_aapl = self.CalculateRSI(aapl_prices, 14)

        spy_holdings = self.Portfolio[self.symbols["SPY"]].Quantity
        aapl_holdings = self.Portfolio[self.symbols["AAPL"]].Quantity

        if spy_holdings > 0:
            if spy_prices[-2] >= sma_yesterday and spy_close < sma_today:
                self.Liquidate(self.symbols["SPY"])

        if aapl_holdings > 0 and rsi_14_aapl is not None:
            if rsi_14_aapl > 60:
                self.Liquidate(self.symbols["AAPL"])

        if spy_holdings == 0:
            if spy_prices[-2] <= sma_yesterday and spy_close > sma_today:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                target_value = portfolio_value * 0.40
                shares_to_buy = int(target_value / spy_close)
                if shares_to_buy > 0:
                    self.MarketOrder(self.symbols["SPY"], shares_to_buy)

        if aapl_holdings == 0:
            consecutive_red = self.CountConsecutiveRed(aapl_prices)
            if consecutive_red >= 3:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares_to_buy = int(20000 / aapl_close)
                    if shares_to_buy > 0:
                        self.MarketOrder(self.symbols["AAPL"], shares_to_buy)

    def CalculateRSI(self, prices, period):
        if len(prices) < period + 1:
            return None

        recent_prices = prices[-(period + 1):]
        deltas = [recent_prices[i + 1] - recent_prices[i] for i in range(len(recent_prices) - 1)]

        gains = [d if d > 0 else 0 for d in deltas]
        losses = [-d if d < 0 else 0 for d in deltas]

        avg_gain = sum(gains[-period:]) / period
        avg_loss = sum(losses[-period:]) / period

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 50

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        return rsi

    def CountConsecutiveRed(self, prices):
        if len(prices) < 2:
            return 0

        count = 0
        for i in range(len(prices) - 1, 0, -1):
            if prices[i] < prices[i - 1]:
                count += 1
            else:
                break

        return count

