        self.spy_prev_close = None
        self.spy_prev_sma = None

        # Track AAPL red day streak
        self.aapl_prev_close = None
        self.aapl_consecutive_red_days = 0

        # Track positions for each strategy
        self.strategy_a_quantity = 0
        self.strategy_b_quantity = 0

    def OnData(self, data):
        # Check if all required symbols have data today
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            if self.symbols[ticker] not in data:
                return

        # Check if indicators are ready
        if not self.spy_sma_100.IsReady or not self.aapl_rsi_14.IsReady:
            return

