        self.aapl_closes.append(aapl_close)

        if len(self.aapl_closes) > 1:
            if aapl_close < self.aapl_closes[-2]:
                self.aapl_red_days += 1
            else:
                self.aapl_red_days = 0

        if len(self.spy_closes) < 101:
            return

        today_sma = sum(self.spy_closes[-100:]) / 100
        yesterday_sma = sum(self.spy_closes[-101:-1]) / 100

        if len(self.aapl_closes) < 15:
            return

        aapl_rsi = self.CalculateRSI(self.aapl_closes, 14)

        spy_holdings = self.Portfolio["SPY"].Quantity
        aapl_holdings = self.Portfolio["AAPL"].Quantity

        yesterday_spy = self.spy_closes[-2]

        if spy_holdings > 0:
            if yesterday_spy >= yesterday_sma and spy_close < today_sma:
                self.Liquidate("SPY")
                spy_holdings = 0

        if spy_holdings == 0:
            if yesterday_spy <= yesterday_sma and spy_close > today_sma:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                target_value = portfolio_value * 0.40
                shares_to_buy = int(target_value / spy_close)
                if shares_to_buy > 0:
                    self.Buy("SPY", shares_to_buy)

        if aapl_holdings > 0:
            if aapl_rsi > 60:
                self.Liquidate("AAPL")
                aapl_holdings = 0

        if aapl_holdings == 0:
            if self.aapl_red_days >= 3:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares_to_buy = int(20000 / aapl_close)
                    if shares_to_buy > 0:
                        self.Buy("AAPL", shares_to_buy)

    def CalculateRSI(self, closes, period):
        if len(closes) < period + 1:
            return 50

        recent_closes = closes[-(period+1):]

        gains = []
        losses = []

        for i in range(1, len(recent_closes)):
            change = recent_closes[i] - recent_closes[i-1]
            if change > 0:
                gains.append(change)
                losses.append(0)
            else:
                gains.append(0)
                losses.append(-change)

        avg_gain = sum(gains) / period
        avg_loss = sum(losses) / period

        if avg_loss == 0:
            return 100

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))

        return rsi

